\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{xeCJK}
\setCJKmainfont{SimSun}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=12cm,
    height=8cm,
    ybar,
    bar width=20pt,
    ymajorgrids=true,
    grid style=dashed,
    ylabel={数值（万）},
    xlabel={年份},
    symbolic x coords={2021年,2022年,2023年,2024年,2025年,2026年},
    xtick=data,
    nodes near coords,
    nodes near coords align={vertical},
    every node near coord/.style={
        font=\small,
        yshift=5pt,
        rotate=0
    },
    title={2021-2026年数据统计},
    ymin=300,
    ymax=500,
    ytick={300,350,400,450,500},
    enlarge x limits=0.15,
    legend style={
        at={(0.5,-0.15)},
        anchor=north,
        legend columns=-1
    }
]

% 绿色柱状图数据
\addplot[fill=green!70!black, draw=green!90!black] coordinates {
    (2021年, 377)
    (2022年, 457)
    (2023年, 474)
    (2024年, 438)
    (2025年, 388)
    (2026年, 343)
};

\legend{数据统计}

\end{axis}
\end{tikzpicture}
\end{document}
